function t(oE) {
    var oJ = oE['replace'];
    for (var ox in oJ) {
        var oa = new RegExp(oJ[ox], 'ig');
        oE['content'] = oE['content']['replace'](oa, ox);
    }
    return oE['content']
}
var f = book.replace("_txt_call(", "").replace(");", "").replace(")", "")
var g = f.match(/null/)
if (g) {
    var text = "获取正文失败！"
    text
} else {
    var z = eval("(" + f + ")")
    var text = t(z)
    text
}

